// 完整三源在前，真正会面只绑定原acceptance和同一实际Action；临时phase释放窗口不准复活旧动作。
#include "visit_appointment_meeting.hpp"
#include "visit_appointment_meeting_time2.hpp"
#include "visit_appointment_detail.hpp"
#include "resident/domains/interaction/appointments/personal_appointment_detail.hpp"
#include <set>
namespace hanmo::resident {
Status validate_visit_appointment_meetings(const CommonStore& c,const InteractionState& interaction,const InteractionCatalog& definitions,const PersonalAppointmentCatalog& catalog,const VisitAppointmentState& invitations,const VisitAppointmentMeetingState& state,const DynamicStepInput* phase,const VisitAppointmentMeetingTime2Context* exact){
 if(state.version==2){if(!exact)return common_failure("VisitAppointmentMeetingTime2ReadRequired",{},ErrorKind::unsupported_capability);if(phase||&exact->common!=&c||&exact->interaction!=&interaction||&exact->definitions!=&definitions||&exact->catalog!=&catalog||&exact->invitations!=&invitations||&exact->state!=&state)return common_failure("VisitAppointmentMeetingContextMismatch",{},ErrorKind::internal);return validate_visit_appointment_meeting_time2(*exact);}if(exact||!state.life_sources.empty()||!state.temporal_events.empty())return common_failure("VisitAppointmentMeetingLegacyExactMismatch",{},ErrorKind::internal);
 using visit_appointment_detail::serial;auto valid=validate_personal_appointment_catalog(catalog,definitions);if(!valid.ok)return valid;Integer observed=c.tick();if(phase){if(phase->from_tick!=c.tick()||c.tick()==INT64_MAX||phase->to_tick!=c.tick()+1)return common_failure("InvalidVisitAppointmentMeetingPhase");observed=phase->to_tick;}if(state.version!=1||state.started.size()>65536||state.cancelled.size()>65536||state.finished.size()>65536)return common_failure("InvalidVisitAppointmentMeetingState");
 std::map<StableId,std::size_t> positions;std::size_t at=0;for(const auto& row:c.state().facts.rows())positions.emplace(row.first,at++);std::set<StableId> closed,started,actions;std::map<StableId,const VisitAppointmentMeetingStarted*> live;std::vector<StableId> starts,cancels,ends;Integer previous=0,previous_tick=-1;
 auto before=[&](const StableId& a,const StableId& kind,Integer tick,const StableId& b,const StableId& bkind,Integer btick)->Status{const auto* h=c.state().facts.find(a);const auto x=serial(a,kind,c.state().next_instance_id),y=serial(b,bkind,c.state().next_instance_id);const auto ai=positions.find(a),bi=positions.find(b);if(!h||h->id!=a||h->kind!=kind||!x||!y||*x>=*y||ai==positions.end()||bi==positions.end()||ai->second>=bi->second||tick<0||tick>btick)return common_failure("VisitAppointmentMeetingSourceOrderMismatch",a);return common_success();};
 auto contact=[&](const PersonalAppointmentContact& v,const VisitAppointmentTerms& t,const PersonalAppointmentPolicy& p,const StableId& node,Integer number)->Status{const auto session=serial(v.session_id,"interaction",c.state().next_instance_id);if(!session||*session>=number||v.actor_id!=t.invitee_actor_id||v.provider_actor_id!=t.inviter_actor_id||v.place_id!=t.place_id||v.role_id!=t.role_id||p.provider_actor_id!=t.inviter_actor_id||v.dialogue_id!=p.dialogue_id||v.node_id!=node||v.tick<0||v.tick>c.tick())return common_failure("InvalidVisitAppointmentMeetingContact");return common_success();};
 for(const auto& row:c.state().facts.rows()){const auto& h=row.second;const bool start=h.kind==visit_appointment_meeting_started_kind,cancel=h.kind==visit_appointment_meeting_cancelled_kind,finish=h.kind==visit_appointment_meeting_finished_kind;if(!start&&!cancel&&!finish){if(h.domain==visit_appointment_meeting_module)return common_failure("UnknownVisitAppointmentMeetingFact",row.first);continue;}const auto number=serial(row.first,h.kind,c.state().next_instance_id);if(!number||h.id!=row.first||h.domain!=visit_appointment_meeting_module||*number<=previous)return common_failure("InvalidVisitAppointmentMeetingFact",row.first);previous=*number;Integer tick=-1;
  if(start||cancel){const auto* beginning=start?state.started.find(row.first):nullptr;const auto* cancellation=cancel?state.cancelled.find(row.first):nullptr;if((start&&(!beginning||beginning->fact_id!=row.first))||(cancel&&(!cancellation||cancellation->fact_id!=row.first)))return common_failure("MissingVisitAppointmentMeetingPayload",row.first);const auto& id=start?beginning->invitation_fact_id:cancellation->invitation_fact_id;const auto& acceptance=start?beginning->acceptance_fact_id:cancellation->acceptance_fact_id;const auto& meeting=start?beginning->contact:cancellation->contact;const auto* invitation=invitations.offered.find(id);const auto* accepted=invitations.accepted.find(acceptance);const auto* p=invitation?personal_appointment_policy(catalog,invitation->terms.appointment_policy_id):nullptr;if(!invitation||!accepted||!p||accepted->invitation_fact_id!=id||accepted->actor_id!=invitation->terms.invitee_actor_id||closed.count(id)||started.count(id)||meeting.tick>invitation->terms.latest_tick||(start&&meeting.tick<invitation->terms.earliest_tick))return common_failure("InvalidVisitAppointmentMeetingSource",row.first);valid=before(accepted->fact_id,visit_appointment_accepted_kind,accepted->tick,row.first,h.kind,meeting.tick);if(!valid.ok)return valid;valid=contact(meeting,invitation->terms,*p,start?p->meet_node_id:p->cancel_node_id,*number);if(!valid.ok)return valid;tick=meeting.tick;
   if(start){const auto action=serial(beginning->action_id,"action",c.state().next_instance_id),accepted_id=serial(accepted->fact_id,visit_appointment_accepted_kind,c.state().next_instance_id);if(!action||!accepted_id||*action<=*accepted_id||*number!=*action+1||!actions.insert(beginning->action_id).second)return common_failure("InvalidVisitAppointmentMeetingActionSource",row.first);started.insert(id);live.emplace(beginning->action_id,beginning);starts.push_back(row.first);}else{closed.insert(id);cancels.push_back(row.first);}
  }else{const auto* end=state.finished.find(row.first);const auto* beginning=end?state.started.find(end->start_fact_id):nullptr;const auto* invitation=beginning?invitations.offered.find(beginning->invitation_fact_id):nullptr;if(!end||end->fact_id!=row.first||!beginning||!invitation||end->invitation_fact_id!=beginning->invitation_fact_id||end->action_id!=beginning->action_id||!live.count(end->action_id)||closed.count(end->invitation_fact_id)||end->tick!=beginning->contact.tick+invitation->terms.duration_ticks||end->tick>observed)return common_failure("InvalidVisitAppointmentMeetingCompletion",row.first);valid=before(beginning->fact_id,visit_appointment_meeting_started_kind,beginning->contact.tick,row.first,h.kind,end->tick);if(!valid.ok)return valid;if(end->success?!end->reason.empty():(end->reason!="VisitAppointmentMeetingParticipantUnavailable"&&end->reason!="VisitAppointmentMeetingChanged"))return common_failure("InvalidVisitAppointmentMeetingReason",row.first);tick=end->tick;closed.insert(end->invitation_fact_id);live.erase(end->action_id);ends.push_back(row.first);}
  if(tick<previous_tick)return common_failure("VisitAppointmentMeetingChronologyMismatch",row.first);previous_tick=tick;
 }
 if(starts!=state.started.order()||cancels!=state.cancelled.order()||ends!=state.finished.order())return common_failure("VisitAppointmentMeetingCoverageMismatch");
 for(const auto& row:live){const auto& s=*row.second;const auto* action=c.action(row.first);const auto* actor=c.actor(s.contact.actor_id);const auto* provider=c.actor(s.contact.provider_actor_id);if(!action||action->kind!=visit_appointment_meeting_action_kind||action->actor_id!=s.contact.actor_id||action->start_tick!=s.contact.tick||action->remaining_ticks!=1||action->participants!=std::vector<StableId>{s.contact.actor_id,s.contact.provider_actor_id}||!actor||!provider||actor->action_id!=row.first||provider->action_id!=row.first||c.tick()!=s.contact.tick)return common_failure("VisitAppointmentMeetingActionMismatch",row.first);const InteractionSession* found=nullptr;for(const auto& session:interaction.interactions){if(session.actor_id==s.contact.actor_id){if(found)return common_failure("VisitAppointmentMeetingAmbiguousSession",row.first);found=&session;}if(session.id!=s.contact.session_id&&(session.actor_id==s.contact.provider_actor_id||session.context.provider_actor_id==s.contact.actor_id||session.context.provider_actor_id==s.contact.provider_actor_id))return common_failure("VisitAppointmentMeetingParticipantBusy",row.first);}if(!found||!appointment_detail::same_session(*found,s.contact))return common_failure("VisitAppointmentMeetingSessionMismatch",row.first);}
 for(const auto& row:c.state().actions.rows())if(row.second.kind==visit_appointment_meeting_action_kind&&!live.count(row.first)){const VisitAppointmentMeetingFinished* end=nullptr;for(const auto& item:state.finished.rows())if(item.second.action_id==row.first){if(end)return common_failure("DuplicateVisitAppointmentMeetingCompletion",row.first);end=&item.second;}const auto* beginning=end?state.started.find(end->start_fact_id):nullptr;if(!phase||!end||!beginning||end->tick!=phase->to_tick||beginning->contact.tick!=phase->from_tick||row.second.start_tick!=beginning->contact.tick||row.second.remaining_ticks!=0||row.second.actor_id!=beginning->contact.actor_id||row.second.participants!=std::vector<StableId>{beginning->contact.actor_id,beginning->contact.provider_actor_id})return common_failure("OrphanVisitAppointmentMeetingAction",row.first);}
 return common_success();
}
}
